add_filter( 'woocommerce_email_recipient_cancelled_order', 'perfectpixel_cancelled_email_to_customer', 20, 2 );

function perfectpixel_cancelled_email_to_customer( $recipient, $order ) {
	if ( $order instanceof WC_Order && $order->get_billing_email() ) {
		$recipient = trim( $recipient . ',' . $order->get_billing_email(), ',' );
	}
	return $recipient;
}
